import{_ as a,o as n,a as p,b as c}from"./app.DKoEZOcr.js";const l="/ascendc.github.io/pr/5487/assets/operator_project_compilation_diagram.BD6Sx5lL.png",v=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"编程指南","link":"/guide/programming_guide/document_structure"},{"text":"高级编程","link":"/guide/programming_guide/advanced_programming/advanced_programming"},{"text":"Aclnn算子工程化开发","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/overview"},{"text":"编译与部署","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/compilation_and_deployment/basic_process"},{"text":"基本流程","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/compilation_and_deployment/basic_process"}]},"headers":[],"relativePath":"guide/programming_guide/advanced_programming/aclnn_operator_development/compilation_and_deployment/basic_process.md","filePath":"guide/programming_guide/advanced_programming/aclnn_operator_development/compilation_and_deployment/basic_process.md","outlineHeaders":[{"level":3,"title":"基本流程","slug":"基本流程","link":"#基本流程"},{"level":2,"title":"编译配置","slug":"编译配置","link":"#编译配置"},{"level":3,"title":"方式一：修改CMakePresets.json","slug":"方式一：修改CMakePresets.json","link":"#方式一：修改CMakePresets.json"},{"level":3,"title":"方式二：在CMakeLists.txt中设置","slug":"方式二：在CMakeLists.txt中设置","link":"#方式二：在CMakeLists.txt中设置"},{"level":2,"title":"执行编译","slug":"执行编译","link":"#执行编译"},{"level":2,"title":"算子包部署","slug":"算子包部署","link":"#算子包部署"},{"level":3,"title":"安装算子包","slug":"安装算子包","link":"#安装算子包"},{"level":4,"title":"默认安装（不指定--install-path）","slug":"默认安装（不指定--install-path）","link":"#默认安装（不指定--install-path）"},{"level":3,"title":"部署后的目录结构","slug":"部署后的目录结构","link":"#部署后的目录结构"},{"level":3,"title":"配置自定义算子优先级","slug":"配置自定义算子优先级","link":"#配置自定义算子优先级"},{"level":4,"title":"默认安装场景","slug":"默认安装场景","link":"#默认安装场景"},{"level":4,"title":"指定目录安装场景","slug":"指定目录安装场景","link":"#指定目录安装场景"},{"level":3,"title":"卸载与更新算子包","slug":"卸载与更新算子包","link":"#卸载与更新算子包"},{"level":4,"title":"卸载算子包","slug":"卸载算子包","link":"#卸载算子包"},{"level":4,"title":"更新算子包","slug":"更新算子包","link":"#更新算子包"},{"level":2,"title":"编译组织（进阶）","slug":"编译组织（进阶）","link":"#编译组织（进阶）"},{"level":3,"title":"按Host/核函数（Kernel）划分的目录结构","slug":"按Host/核函数（Kernel）划分的目录结构","link":"#按Host/核函数（Kernel）划分的目录结构"},{"level":3,"title":"按算子划分的目录结构","slug":"按算子划分的目录结构","link":"#按算子划分的目录结构"},{"level":2,"title":"自定义编译选项（进阶）","slug":"自定义编译选项（进阶）","link":"#自定义编译选项（进阶）"},{"level":2,"title":"相关文档","slug":"相关文档","link":"#相关文档"}],"lastUpdated":1788139350000}'),e={name:"guide/programming_guide/advanced_programming/aclnn_operator_development/compilation_and_deployment/basic_process.md"};function o(t,s,d,i,r,_){return n(),p("div",null,[...s[0]||(s[0]=[c('<div><article class="markdown-body"><h1>编译与部署基本流程</h1><p>本文是基础内容，介绍算子核函数（Kernel）侧和Host侧实现开发完成后，如何对算子工程进行编译、生成自定义算子安装包*.run。详细的编译操作包括：</p><ul><li><p>编译Ascend C算子核函数（Kernel）侧代码实现文件*.cpp，分为源码发布和二进制发布两种方式。</p><ul><li><strong>源码发布</strong><a id="source-release"></a>：不对算子核函数（Kernel）侧实现进行编译，保留算子核函数（Kernel）源码文件*.cpp。该方式可以支持算子的在线编译、通过ATC模型转换的方式编译算子的场景。</li><li><strong>二进制发布</strong>：对算子核函数（Kernel）侧实现进行编译，生成描述算子相关信息的json文件*.json和算子二进制文件*.o。算子调用时，如果需要直接调用算子二进制，则使用该编译方式，比如通过<a href="../invocation/single_operator_api_call.html">单算子API调用</a>的方式完成单算子的调用，PyTorch框架中单算子调用的场景，动态网络中调用算子的场景。</li></ul></li><li><p>编译Ascend C算子Host侧代码实现文件*.cpp、*.h。</p><ul><li>将原型定义和shape推导实现编译成算子原型定义动态库libcust_opsproto_*.so，并生成算子原型对外接口op_proto.h。</li><li>将Tiling实现编译成Tiling动态库liboptiling.so等。</li><li>基于算子原型定义，自动生成单算子API调用代码和头文件aclnn_*.h，并编译生成单算子API调用的动态库libcust_opapi.so。</li></ul></li></ul><p>上述编译过程示意图如下：</p><p><img src="'+l+`" alt title="算子工程编译示意图"></p><h3 id="基本流程">基本流程<a class="header-anchor" href="#基本流程">​</a></h3><p>使用msOpGen生成的工程，已经包含完整CMake结构，不需要单独编写CMakeLists.txt处理；如果需要自行编写CMakeLists.txt，请参考<a href="#%E7%BC%96%E8%AF%91%E7%BB%84%E7%BB%87">编译组织</a>。以<a href="../aclnn_quick_start.html">快速入门的AddCustom</a>为例，msOpGen生成的算子工程编译部署只需三步：</p><ol><li>修改<code>CMakePresets.json</code>，填写<code>ASCEND_SOC_SERIES</code>或<code>ASCEND_COMPUTE_UNIT</code>（二选一）以及<code>vendor_name</code>（厂商名称）等编译配置选项；</li><li>执行<code>./build.sh</code>，生成<code>custom_opp_*.run</code>安装包；</li><li>执行<code>./custom_opp_*.run</code>，安装到运行环境。</li></ol><p>以下各节详细介绍每一步的选项和细节。</p><h2 id="编译配置">编译配置<a id="compile-configuration"></a><a class="header-anchor" href="#编译配置">​</a></h2><p>编译配置选项的必改参数有两个，其中芯片系列配置在<code>ASCEND_SOC_SERIES</code>和<code>ASCEND_COMPUTE_UNIT</code>中二选一：</p><table><thead><tr><th>参数名称</th><th>参数描述</th><th>默认值</th></tr></thead><tbody><tr><td>ASCEND_SOC_SERIES</td><td>AI处理器系列，支持配置一个或多个值。输入不区分大小写，配置值会先归一为小写。</td><td>无</td></tr><tr><td>ASCEND_COMPUTE_UNIT</td><td>AI处理器型号，按实际运行芯片配置。</td><td>&quot;ascendxxx&quot;</td></tr><tr><td>vendor_name</td><td>自定义算子所属厂商名称，用于形成<code>vendors/&lt;vendor_name&gt;</code>安装目录，避免与其他厂商算子包冲突；同一安装路径下<code>vendor_name</code>相同的算子包会安装到同一目录，同名文件会覆盖。</td><td>&quot;customize&quot;</td></tr></tbody></table><p><code>ASCEND_SOC_SERIES</code>与<code>ASCEND_COMPUTE_UNIT</code>不能同时配置，且<code>ASCEND_SOC_SERIES</code>不能为空。</p><p>除上述必改参数外，其他可选编译配置选项详情如下：</p><table><thead><tr><th>类型</th><th>选项名</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td>STRING</td><td>CMAKE_BUILD_TYPE</td><td>Release</td><td>编译类型，支持Release和Debug，Release版本：不包含调试信息，编译最终发布的版本；Debug版本：包含调试信息，用于开发调试。</td></tr><tr><td>PATH</td><td>ASCEND_AUTOGEN_PATH</td><td>&lt;CMAKE_BINARY_DIR&gt;/autogen</td><td>自动生成代码的存放路径。</td></tr><tr><td>PATH</td><td>ASCEND_CANN_PACKAGE_PATH</td><td>-</td><td>CANN软件包路径，默认路径示例如下：/usr/local/Ascend/cann。</td></tr><tr><td>BOOL</td><td>ENABLE_SOURCE_PACKAGE</td><td>TRUE</td><td>是否开启源码编译，如果使用npu_op_package配置了源码和二进制编译相关配置，npu_op_package配置的优先级更高。</td></tr><tr><td>BOOL</td><td>ENABLE_BINARY_PACKAGE</td><td>TRUE</td><td>是否开启二进制编译，package的类型配置为SHARED或STATIC时，必须指定为TRUE。如果使用npu_op_package配置了源码和二进制编译相关配置，npu_op_package配置的优先级更高。</td></tr><tr><td>BOOL</td><td>ENABLE_CROSS_COMPILE</td><td>FALSE</td><td>是否启用交叉编译，参考<a href="./cross_compilation.html">交叉编译</a>。</td></tr><tr><td>PATH</td><td>CMAKE_CROSS_PLATFORM_COMPILER</td><td>/your/cross/compiler/path</td><td>交叉编译工具路径。</td></tr><tr><td>BOOL</td><td>ASCEND_PACK_SHARED_LIBRARY</td><td>FALSE</td><td>是否开启动态库编译。</td></tr><tr><td>BOOL</td><td>ASCEND_SKIP_FAILED_COMPUTE_UNIT</td><td>FALSE</td><td>该参数用于控制部分AI处理器型号对应的算子编译失败时，是否跳过失败并继续编译其他型号的算子，设置成True为跳过失败，跳过失败不影响其他AI处理器型号对应算子的编译流程；设置成False，遇到失败会影响其他AI处理器型号对应算子的编译流程。</td></tr></tbody></table><p>修改编译配置选项的方式有两种：</p><h3 id="方式一：修改CMakePresets.json">方式一：修改CMakePresets.json<a class="header-anchor" href="#方式一：修改CMakePresets.json">​</a></h3><p>工程目录下有<code>CMakePresets.json</code>时，修改其中的<code>cacheVariables</code>即可。msOpGen生成的工程默认使用此方式。</p><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>直接执行<code>cmake --preset=default</code>要求CMake &gt;= 3.19。msOpGen生成的<code>build.sh</code>会在低版本CMake环境下解析<code>CMakePresets.json</code>并转成普通<code>cmake -D</code>参数，因此优先建议使用工程自带的<code>build.sh</code>。</p></div><p><strong>最小配置示例</strong>：</p><div class="code-block"><div class="code-header"><span class="lang-label">JSON</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="p">{</span>
<span class="w">    </span><span class="nt">&quot;version&quot;</span><span class="p">:</span><span class="w"> </span><span class="mi">1</span><span class="p">,</span>
<span class="w">    </span><span class="nt">&quot;cmakeMinimumRequired&quot;</span><span class="p">:</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="nt">&quot;major&quot;</span><span class="p">:</span><span class="w"> </span><span class="mi">3</span><span class="p">,</span>
<span class="w">        </span><span class="nt">&quot;minor&quot;</span><span class="p">:</span><span class="w"> </span><span class="mi">19</span><span class="p">,</span>
<span class="w">        </span><span class="nt">&quot;patch&quot;</span><span class="p">:</span><span class="w"> </span><span class="mi">0</span>
<span class="w">    </span><span class="p">},</span>
<span class="w">    </span><span class="nt">&quot;configurePresets&quot;</span><span class="p">:</span><span class="w"> </span><span class="p">[</span>
<span class="w">        </span><span class="p">{</span>
<span class="w">            </span><span class="nt">&quot;name&quot;</span><span class="p">:</span><span class="w"> </span><span class="s2">&quot;default&quot;</span><span class="p">,</span>
<span class="w">            </span><span class="nt">&quot;cacheVariables&quot;</span><span class="p">:</span><span class="w"> </span><span class="p">{</span>
<span class="w">                </span><span class="nt">&quot;ASCEND_COMPUTE_UNIT&quot;</span><span class="p">:</span><span class="w"> </span><span class="p">{</span>
<span class="w">                    </span><span class="nt">&quot;type&quot;</span><span class="p">:</span><span class="w"> </span><span class="s2">&quot;STRING&quot;</span><span class="p">,</span>
<span class="w">                    </span><span class="nt">&quot;value&quot;</span><span class="p">:</span><span class="w"> </span><span class="s2">&quot;ascendxxyy&quot;</span>
<span class="w">                </span><span class="p">},</span>
<span class="w">                </span><span class="nt">&quot;vendor_name&quot;</span><span class="p">:</span><span class="w"> </span><span class="p">{</span>
<span class="w">                    </span><span class="nt">&quot;type&quot;</span><span class="p">:</span><span class="w"> </span><span class="s2">&quot;STRING&quot;</span><span class="p">,</span>
<span class="w">                    </span><span class="nt">&quot;value&quot;</span><span class="p">:</span><span class="w"> </span><span class="s2">&quot;customize&quot;</span>
<span class="w">                </span><span class="p">}</span>
<span class="w">            </span><span class="p">}</span>
<span class="w">        </span><span class="p">}</span>
<span class="w">    </span><span class="p">]</span>
<span class="p">}</span>
</code></pre></div><h3 id="方式二：在CMakeLists.txt中设置">方式二：在CMakeLists.txt中设置<a class="header-anchor" href="#方式二：在CMakeLists.txt中设置">​</a></h3><p>直接在顶层CMakeLists.txt中设置变量，并通过<code>npu_op_*</code>接口配置编译行为，无需CMakePresets.json文件。</p><div class="code-block"><div class="code-header"><span class="lang-label">CMake</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c"># 设置必要变量。也可以使用变量ASCEND_SOC_SERIES，二者不能同时设置。</span>
<span class="nb">set</span><span class="p">(</span><span class="s">ASCEND_COMPUTE_UNIT</span><span class="w"> </span><span class="s2">&quot;ascendxxxyy&quot;</span><span class="p">)</span><span class="w"> </span><span class="err">|</span><span class="w"> </span><span class="nb">set</span><span class="p">(</span><span class="s">ASCEND_SOC_SERIES</span><span class="w"> </span><span class="s2">&quot;Ascendxxx&quot;</span><span class="p">)</span>
<span class="nb">set</span><span class="p">(</span><span class="s">vendor_name</span><span class="w"> </span><span class="s2">&quot;customize&quot;</span><span class="p">)</span>

<span class="c"># 配置编译产物包（通过CONFIG参数替代ENABLE_SOURCE_PACKAGE / ENABLE_BINARY_PACKAGE等变量）</span>
<span class="nb">npu_op_package</span><span class="p">(</span><span class="o">\${</span><span class="nv">vendor_name</span><span class="o">}</span>
<span class="w">    </span><span class="s">TYPE</span><span class="w"> </span><span class="s">RUN</span>
<span class="w">    </span><span class="s">CONFIG</span>
<span class="w">        </span><span class="s">ENABLE_SOURCE_PACKAGE</span><span class="w"> </span><span class="s">True</span>
<span class="w">        </span><span class="s">ENABLE_BINARY_PACKAGE</span><span class="w"> </span><span class="s">True</span>
<span class="w">        </span><span class="s">INSTALL_PATH</span><span class="w"> </span><span class="o">\${</span><span class="nv">CMAKE_BINARY_DIR</span><span class="o">}</span><span class="s">/</span>
<span class="p">)</span>
</code></pre></div><p>其他配置（如动态库编译、交叉编译等）也可在CMakeLists.txt中通过变量或<code>npu_op_package</code> CONFIG参数设置。完整参数说明请参考<a href="../appendix/cmake_function_reference.html">cmake函数参考</a>。</p><p>需要注意如果<code>npu_op_package(... CONFIG ...)</code>中硬编码了<code>ENABLE_SOURCE_PACKAGE</code>或<code>ENABLE_BINARY_PACKAGE</code>的值（如本节样例直接写True），命令行或<code>CMakePresets.json</code>中的同名变量将无法覆盖。要允许外部变量生效，CONFIG中应使用<code>\${ENABLE_SOURCE_PACKAGE}</code>、<code>\${ENABLE_BINARY_PACKAGE}</code>变量形式。</p><h2 id="执行编译">执行编译<a class="header-anchor" href="#执行编译">​</a></h2><p>有两种编译方法：</p><p><strong>方法一：使用build.sh脚本</strong></p><p>如果工程目录下有<code>build.sh</code>脚本（msOpGen生成的工程默认提供），直接执行：</p><div class="code-block"><div class="code-header"><span class="lang-label">Bash</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>./build.sh
</code></pre></div><p><strong>方法二：执行cmake命令</strong></p><div class="code-block"><div class="code-header"><span class="lang-label">Bash</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>cmake<span class="w"> </span>-S<span class="w"> </span>.<span class="w"> </span>-B<span class="w"> </span>build_out<span class="w"> </span>--preset<span class="o">=</span>default
cmake<span class="w"> </span>--build<span class="w"> </span>build_out<span class="w"> </span>--target<span class="w"> </span>binary<span class="w"> </span>package<span class="w"> </span>-j<span class="k">$(</span>nproc<span class="k">)</span>
</code></pre></div><ul><li><p><code>cmake -S . -B build_out --preset=default</code>是CMake的配置和生成阶段：从当前目录读取源码、<code>CMakeLists.txt</code>和<code>CMakePresets.json</code>中的<code>default</code>配置，在<code>build_out</code>目录下生成后续编译需要的构建文件。</p></li><li><p><code>cmake --build build_out --target binary package -j$(nproc)</code>是实际编译和打包阶段：使用<code>build_out</code>中已经生成的构建文件，执行<code>binary</code>和<code>package</code>目标；<code>binary</code>负责编译算子二进制相关产物，<code>package</code>负责生成算子安装包，<code>-j$(nproc)</code>表示按当前机器CPU核数并行编译。</p></li></ul><p>编译成功后，会在编译产物目录下生成自定义算子安装包<code>custom_opp_&lt;target os&gt;_&lt;target architecture&gt;.run</code>。该run包包含算子原型库、Tiling库、aclnn API库和核函数（Kernel）二进制，部署后框架会自动扫描并加载。</p><p><strong>编译日志存储</strong>（可选）：</p><p>用户如果需要编译过程日志存盘，可以使用环境变量ASCENDC_BUILD_LOG_DIR来控制存储路径。用户设置该选项之后，如果编译过程中无错误产生，则对应的log文件后缀会添加&quot;_success&quot;，若编译过程有错误产生，则会在屏幕打印对应的报错信息，以及指示用户log文件的具体路径与文件名，同时，对应log文件后缀会添加“_error”。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code># 如希望编译日志存储在/home/build_log/，则可以按照如下设置，默认不打开日志存储
export ASCENDC_BUILD_LOG_DIR=/home/build_log/
</code></pre></div><p><a id="算子包部署"></a></p><h2 id="算子包部署">算子包部署<a id="operator-package-deployment"></a><a class="header-anchor" href="#算子包部署">​</a></h2><p>编译生成的算子安装包需要部署到运行环境。</p><h3 id="安装算子包">安装算子包<a class="header-anchor" href="#安装算子包">​</a></h3><p>在自定义算子包所在路径下，执行安装命令：</p><div class="code-block"><div class="code-header"><span class="lang-label">Bash</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1"># source CANN包的环境变量，以默认安装路径为例</span>
<span class="nb">source</span><span class="w"> </span>/usr/local/Ascend/cann/set_env.sh
<span class="c1"># 安装自定义算子run包</span>
./custom_opp_&lt;target<span class="w"> </span>os&gt;_&lt;target<span class="w"> </span>architecture&gt;.run<span class="w"> </span>--install-path<span class="o">=</span>&lt;path&gt;
</code></pre></div><p><code>--install-path</code>是可选参数，指定安装目录。支持绝对路径，要求对目标路径有读写权限。</p><h4 id="默认安装（不指定--install-path）">默认安装（不指定--install-path）<a class="header-anchor" href="#默认安装（不指定--install-path）">​</a></h4><p>安装到<code>$ASCEND_OPP_PATH/vendors/&lt;vendor_name&gt;</code>目录（<code>$ASCEND_OPP_PATH</code>通常等于<code>\${CANN安装路径}/opp</code>，以默认安装路径为例：<code>/usr/local/Ascend/cann/opp</code>）。</p><blockquote><p><strong>路径关系说明</strong>：默认安装场景下，算子包部署到<code>$ASCEND_OPP_PATH/vendors/&lt;vendor_name&gt;</code>。安装脚本会将当前vendor写入<code>$ASCEND_OPP_PATH/vendors/config.ini</code>的<code>load_priority</code>配置项，框架按照该配置加载默认路径中的算子包。</p></blockquote><p><strong>表3</strong> 默认安装与指定目录安装对比。</p><table><thead><tr><th>安装方式</th><th>安装命令</th><th>安装路径</th><th>自定义算子包安装后是否需要用户自行source自定义算子包的环境变量</th><th>优先级</th></tr></thead><tbody><tr><td>默认安装</td><td><code>./custom_opp_*.run</code></td><td><code>\${ASCEND_OPP_PATH}/vendors/&lt;vendor_name&gt;</code></td><td>否，自动生效</td><td>较低</td></tr><tr><td>指定目录安装</td><td><code>./custom_opp_*.run --install-path=&lt;path&gt;</code></td><td><code>&lt;path&gt;/vendors/&lt;vendor_name&gt;</code></td><td>是，需要source环境变量</td><td>较高</td></tr></tbody></table><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><ul><li>默认安装路径权限与CANN软件包安装用户和配置有关，如果因权限不足导致安装失败，可使用指定目录安装或联系CANN安装用户修改权限。</li><li>指定目录安装后，在调用算子前需要执行<code>source &lt;path&gt;/vendors/&lt;vendor_name&gt;/bin/set_env.bash</code>。该脚本会将算子包目录<code>&lt;path&gt;/vendors/&lt;vendor_name&gt;</code>添加到<code>ASCEND_CUSTOM_OPP_PATH</code>环境变量的首部，供框架在运行时查找自定义算子包；同时将<code>&lt;path&gt;/vendors/&lt;vendor_name&gt;/op_api/lib/</code>添加到<code>LD_LIBRARY_PATH</code>环境变量的首部，供系统动态链接器查找算子动态库。</li><li>算子包要求架构与系统架构一致，且满足glibc版本依赖，否则可使用<code>--force</code>强制安装。</li></ul></div><p><a id="部署后的目录结构"></a></p><h3 id="部署后的目录结构">部署后的目录结构<a class="header-anchor" href="#部署后的目录结构">​</a></h3><p>以默认安装场景为例：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>├── opp    //算子库目录
│   ├── vendors     //自定义算子所在目录
│       ├── config.ini
│       └── vendor_name1   // 存储对应厂商部署的自定义算子
│           ├── framework     //自定义算子插件库
│           ├── op_api
│           │   ├── include
│           │   │   └── aclnn_xx.h      //算子调用API声明文件
│           │   └── lib
│           │       └── libcust_opapi.so
│           ├── op_impl
│           │   └── ai_core
│           │       └── tbe
│           │           ├── config
│           │           ├── vendor_name1_impl    //自定义算子实现代码文件
│           │           │   └── dynamic
│           │           │       ├── xx.cpp
│           │           │       ├── xx.py
│           │           │       └── xx_tiling.h
│           │           ├── kernel     //自定义算子二进制文件
│           │           │   └── \${soc_version}     //AI处理器类型
│           │           │   └── config
│           │           └── op_tiling
│           │               ├── lib
│           │               └── liboptiling.so
│           ├── op_proto     //自定义算子原型库所在目录
│                ├── inc
│                │   └── op_proto.h
│                └── lib
│           ├── scripts      //算子包维护脚本，如卸载脚本
│           └── version.info //版本信息
</code></pre></div><p><a id="配置自定义算子优先级"></a></p><h3 id="配置自定义算子优先级">配置自定义算子优先级<a class="header-anchor" href="#配置自定义算子优先级">​</a></h3><p>多个算子包共存时，如果包含相同OpType的算子，优先级高的算子包中的版本生效。</p><h4 id="默认安装场景">默认安装场景<a class="header-anchor" href="#默认安装场景">​</a></h4><p>多个算子包包含同名OpType时，可通过配置<code>opp/vendors/config.ini</code>文件调整各自定义算子的加载优先级；其他场景不建议手动修改该文件。<code>opp/vendors/config.ini</code>文件内容如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">INI</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="na">load_priority</span><span class="o">=</span><span class="s">vendor_name1,vendor_name2,vendor_name3</span>
</code></pre></div><p>有效的<code>load_priority</code>配置需要满足以下要求：</p><ul><li>配置项名称必须为<code>load_priority</code>，不可修改。</li><li>等号右侧至少包含一个vendor名称，不能为空。vendor名称应与<code>opp/vendors</code>目录下已安装算子包的目录名一致。</li><li>配置多个vendor时，使用英文逗号分隔。vendor按从左到右的顺序确定优先级，最左侧的vendor优先级最高。</li></ul><p>例如，<code>load_priority=vendor_name1,vendor_name2,vendor_name3</code>是有效配置；<code>load_priority=</code>、缺少<code>load_priority</code>配置项或修改了配置项名称均为无效配置。</p><p>默认安装时，如果<code>config.ini</code>不存在，安装脚本会创建该文件并写入当前vendor；如果文件已存在，安装脚本会基于有效的<code>load_priority</code>配置将当前vendor调整到首位。安装或升级过程中，如果配置无效、文件无法读写或配置更新结果不符合预期，脚本将报错并停止安装或升级，不会自动补全或修正异常配置。</p><h4 id="指定目录安装场景">指定目录安装场景<a id="custom-install-path"></a><a class="header-anchor" href="#指定目录安装场景">​</a></h4><p>分别执行各算子包安装路径下的<code>set_env.bash</code>脚本，脚本执行顺序越靠后，优先级越高。</p><div class="code-block"><div class="code-header"><span class="lang-label">Bash</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="nb">source</span><span class="w"> </span>&lt;path&gt;/vendors/vendor_name1/bin/set_env.bash<span class="w">  </span><span class="c1">#先执行，优先级较低</span>
<span class="nb">source</span><span class="w"> </span>&lt;path&gt;/vendors/vendor_name2/bin/set_env.bash<span class="w">  </span><span class="c1">#后执行，优先级较高</span>
</code></pre></div><p>执行后<code>ASCEND_CUSTOM_OPP_PATH</code>示例：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>ASCEND_CUSTOM_OPP_PATH=&lt;path&gt;/vendors/vendor_name2:&lt;path&gt;/vendors/vendor_name1:
</code></pre></div><h3 id="卸载与更新算子包">卸载与更新算子包<a class="header-anchor" href="#卸载与更新算子包">​</a></h3><h4 id="卸载算子包">卸载算子包<a class="header-anchor" href="#卸载算子包">​</a></h4><p>算子包安装目录中包含<code>uninstall.sh</code>脚本，执行该脚本即可完成卸载：</p><p><strong>默认安装场景</strong>：</p><div class="code-block"><div class="code-header"><span class="lang-label">Bash</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>bash<span class="w"> </span><span class="si">\${</span><span class="nv">INSTALL_DIR</span><span class="si">}</span>/opp/vendors/&lt;vendor_name&gt;/scripts/uninstall.sh
</code></pre></div><p><strong>指定目录安装场景</strong>：</p><div class="code-block"><div class="code-header"><span class="lang-label">Bash</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>bash<span class="w"> </span>&lt;path&gt;/vendors/&lt;vendor_name&gt;/scripts/uninstall.sh
</code></pre></div><h4 id="更新算子包">更新算子包<a class="header-anchor" href="#更新算子包">​</a></h4><p><strong>默认安装场景</strong>：重新执行安装命令即可覆盖旧版本。</p><div class="code-block"><div class="code-header"><span class="lang-label">Bash</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1"># source CANN包的环境变量，以默认路径为例</span>
<span class="nb">source</span><span class="w"> </span>/usr/local/Ascend/cann/set_env.sh
<span class="c1"># 安装自定义算子run包</span>
./custom_opp_&lt;target<span class="w"> </span>os&gt;_&lt;target<span class="w"> </span>architecture&gt;.run
</code></pre></div><p><strong>指定目录安装场景</strong>：先卸载旧版本，再安装新版本。</p><div class="code-block"><div class="code-header"><span class="lang-label">Bash</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1"># 1. 卸载旧版本</span>
bash<span class="w"> </span>&lt;path&gt;/vendors/&lt;vendor_name&gt;/scripts/uninstall.sh

<span class="c1"># 2. 安装新版本</span>
<span class="c1"># source CANN包的环境变量，以默认路径为例</span>
<span class="nb">source</span><span class="w"> </span>/usr/local/Ascend/cann/set_env.sh
<span class="c1"># 安装自定义算子run包</span>
./custom_opp_&lt;target<span class="w"> </span>os&gt;_&lt;target<span class="w"> </span>architecture&gt;.run<span class="w"> </span>--install-path<span class="o">=</span>&lt;path&gt;
</code></pre></div><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><ul><li>更新算子包后，需要重新source环境变量（指定目录安装场景）。</li><li>如果需要回退到旧版本，建议先备份旧版本算子包。</li></ul></div><hr><blockquote><p>以上为编译部署的基本流程。以下内容涉及CMake组织和自定义编译选项，适合需要定制编译流程的开发者参考。常规场景下msOpGen生成的工程已包含完整的CMake结构，直接修改<code>CMakePresets.json</code>并执行<code>./build.sh</code>即可。</p></blockquote><hr><p><a id="编译组织"></a></p><h2 id="编译组织（进阶）">编译组织（进阶）<a id="advanced-build-organization"></a><a class="header-anchor" href="#编译组织（进阶）">​</a></h2><p>算子工程通过CMake组织编译。如需自行组织工程或用CANN提供的CMake modules定制编译流程，可参考以下内容。</p><p>算子工程的目录组织方式不固定，以下仅示意两种常见方式；也可以将Host、核函数（Kernel）、Tiling文件完全平铺在同一目录，只要CMakeLists.txt正确传入源文件和<code>npu_op_*</code>接口参数即可。</p><table><thead><tr><th>方式</th><th>特点</th><th>适用场景</th></tr></thead><tbody><tr><td>按Host/核函数（Kernel）划分</td><td>Host和核函数（Kernel）代码分目录，三层CMakeLists。</td><td>msOpGen默认生成，单算子或少量算子。</td></tr><tr><td>按算子划分</td><td>每个算子一个独立目录，算子目录维护自己的源文件清单和核函数（Kernel）声明。</td><td>多算子工程，算子间独立性高。</td></tr></tbody></table><p>msOpGen工具默认生成&quot;按Host/核函数（Kernel）划分&quot;的结构。</p><h3 id="按Host/核函数（Kernel）划分的目录结构">按Host/核函数（Kernel）划分的目录结构<a class="header-anchor" href="#按Host/核函数（Kernel）划分的目录结构">​</a></h3><p>所有算子的Host侧代码集中在<code>op_host/</code>目录下，核函数（Kernel）侧代码集中在<code>op_kernel/</code>目录下。工程包含三层CMakeLists.txt：顶层定义算子包并添加子目录，<code>op_host/</code>下编译Host侧库，<code>op_kernel/</code>下编译核函数（Kernel）侧库。</p><p><strong>1. 顶层CMakeLists.txt</strong></p><p>顶层CMakeLists.txt设置编译环境、定义package形态，并添加子目录：</p><ol><li>使用<strong>find_package</strong>找到对应的编译库。</li><li>使用<strong>npu_op_package</strong>设置算子工程的编译产物形态，支持RUN/SHARED/STATIC，分别对应算子run包形式、算子动态库形式与算子静态库形式，同时，该接口还可配置package（即编译产物）的内容和package的安装位置。</li><li>添加需要进行编译的子目录。</li></ol><div class="code-block"><div class="code-header"><span class="lang-label">CMake</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="nb">cmake_minimum_required</span><span class="p">(</span><span class="s">VERSION</span><span class="w"> </span><span class="s">3.19.0</span><span class="p">)</span>
<span class="nb">project</span><span class="p">(</span><span class="s">opp</span><span class="p">)</span>

<span class="c"># 1. 使用find_package查找CANN软件包提供的ASC CMake modules</span>
<span class="nb">find_package</span><span class="p">(</span><span class="s">ASC</span><span class="w"> </span><span class="s">REQUIRED</span><span class="w"> </span><span class="s">HINTS</span><span class="w"> </span><span class="o">\${</span><span class="nv">ASCEND_CANN_PACKAGE_PATH</span><span class="o">}</span><span class="s">/compiler/tikcpp/ascendc_kernel_cmake</span><span class="p">)</span>

<span class="c"># 2. 设置算子工程的编译产物形态</span>
<span class="c"># vendor_name在CMakePresets.json中配置，用于区分不同厂商的算子包</span>
<span class="nb">set</span><span class="p">(</span><span class="s">package_name</span><span class="w"> </span><span class="o">\${</span><span class="nv">vendor_name</span><span class="o">}</span><span class="p">)</span>
<span class="nb">npu_op_package</span><span class="p">(</span><span class="o">\${</span><span class="nv">package_name</span><span class="o">}</span>
<span class="w">    </span><span class="s">TYPE</span><span class="w"> </span><span class="s">RUN</span><span class="w">                                       </span><span class="c">#编译产物形态：RUN/STATIC/SHARED</span>
<span class="w">    </span><span class="s">CONFIG</span>
<span class="w">        </span><span class="s">ENABLE_SOURCE_PACKAGE</span><span class="w"> </span><span class="s">True</span>
<span class="w">        </span><span class="s">ENABLE_BINARY_PACKAGE</span><span class="w"> </span><span class="s">True</span>
<span class="w">        </span><span class="s">INSTALL_PATH</span><span class="w"> </span><span class="o">\${</span><span class="nv">CMAKE_BINARY_DIR</span><span class="o">}</span><span class="s">/</span>
<span class="p">)</span>

<span class="c"># 3. 添加Host和核函数（Kernel）子目录进行编译</span>
<span class="nb">if</span><span class="p">(</span><span class="s">EXISTS</span><span class="w"> </span><span class="o">\${</span><span class="nv">CMAKE_CURRENT_SOURCE_DIR</span><span class="o">}</span><span class="s">/op_host</span><span class="p">)</span>
<span class="w">    </span><span class="nb">add_subdirectory</span><span class="p">(</span><span class="s">op_host</span><span class="p">)</span>
<span class="nb">endif</span><span class="p">()</span>
<span class="nb">if</span><span class="p">(</span><span class="s">EXISTS</span><span class="w"> </span><span class="o">\${</span><span class="nv">CMAKE_CURRENT_SOURCE_DIR</span><span class="o">}</span><span class="s">/op_kernel</span><span class="p">)</span>
<span class="w">    </span><span class="nb">add_subdirectory</span><span class="p">(</span><span class="s">op_kernel</span><span class="p">)</span>
<span class="nb">endif</span><span class="p">()</span>
</code></pre></div><p><strong>TYPE参数说明</strong>：</p><ul><li><code>RUN</code>：生成run包，用于算子部署。</li><li><code>SHARED</code>：生成动态库，用于集成到应用。</li><li><code>STATIC</code>：生成静态库，用于静态链接。</li></ul><p><strong>2. Host侧CMakeLists.txt</strong></p><p><code>op_host/</code>下的CMakeLists.txt生成aclnn调用代码，编译Host侧各类库：</p><ol><li>使用 <strong>npu_op_code_gen</strong> 生成aclnn单算子调用代码、入图所需的原型定义代码等。</li><li>单算子调用场景，使用 <strong>npu_op_library</strong> 编译aclnn单算子调用库。</li><li>算子入图场景，使用<strong>npu_op_library</strong>编译算子入图所需的算子原型库。</li><li>使用 <strong>npu_op_library</strong> 编译Tiling相关库。</li><li>使用<strong>npu_op_package_add</strong>添加上述Host侧库至对应package中。</li></ol><div class="code-block"><div class="code-header"><span class="lang-label">CMake</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="nb">aux_source_directory</span><span class="p">(</span><span class="o">\${</span><span class="nv">CMAKE_CURRENT_SOURCE_DIR</span><span class="o">}</span><span class="w"> </span><span class="s">ops_srcs</span><span class="p">)</span>

<span class="c"># 1. 生成aclnn调用代码和原型定义代码</span>
<span class="nb">npu_op_code_gen</span><span class="p">(</span>
<span class="w">    </span><span class="s">SRC</span><span class="w"> </span><span class="o">\${</span><span class="nv">ops_srcs</span><span class="o">}</span>
<span class="w">    </span><span class="s">PACKAGE</span><span class="w"> </span><span class="o">\${</span><span class="nv">package_name</span><span class="o">}</span>
<span class="w">    </span><span class="s">OUT_DIR</span><span class="w"> </span><span class="o">\${</span><span class="nv">ASCEND_AUTOGEN_PATH</span><span class="o">}</span>
<span class="p">)</span>

<span class="c"># 2. 编译aclnn单算子调用库</span>
<span class="nb">file</span><span class="p">(</span><span class="s">GLOB</span><span class="w"> </span><span class="s">autogen_aclnn_src</span><span class="w"> </span><span class="o">\${</span><span class="nv">ASCEND_AUTOGEN_PATH</span><span class="o">}</span><span class="s">/aclnn_*.cpp</span><span class="p">)</span>
<span class="nb">set_source_files_properties</span><span class="p">(</span><span class="o">\${</span><span class="nv">autogen_aclnn_src</span><span class="o">}</span><span class="w"> </span><span class="s">PROPERTIES</span><span class="w"> </span><span class="s">GENERATED</span><span class="w"> </span><span class="s">TRUE</span><span class="p">)</span>
<span class="nb">npu_op_library</span><span class="p">(</span><span class="s">cust_opapi</span><span class="w"> </span><span class="s">ACLNN</span>
<span class="w">    </span><span class="o">\${</span><span class="nv">autogen_aclnn_src</span><span class="o">}</span>
<span class="p">)</span>
<span class="nb">target_compile_options</span><span class="p">(</span><span class="s">cust_opapi</span><span class="w"> </span><span class="s">PRIVATE</span><span class="w"> </span><span class="s">-fvisibility=hidden</span><span class="p">)</span>

<span class="c"># 3. 编译算子原型库（用于入图）</span>
<span class="nb">file</span><span class="p">(</span><span class="s">GLOB</span><span class="w"> </span><span class="s">proto_src</span><span class="w"> </span><span class="o">\${</span><span class="nv">ASCEND_AUTOGEN_PATH</span><span class="o">}</span><span class="s">/op_proto.cc</span><span class="p">)</span>
<span class="nb">set_source_files_properties</span><span class="p">(</span><span class="o">\${</span><span class="nv">proto_src</span><span class="o">}</span><span class="w"> </span><span class="s">PROPERTIES</span><span class="w"> </span><span class="s">GENERATED</span><span class="w"> </span><span class="s">TRUE</span><span class="p">)</span>
<span class="nb">npu_op_library</span><span class="p">(</span><span class="s">cust_op_proto</span><span class="w"> </span><span class="s">GRAPH</span>
<span class="w">    </span><span class="o">\${</span><span class="nv">ops_srcs</span><span class="o">}</span>
<span class="w">    </span><span class="o">\${</span><span class="nv">proto_src</span><span class="o">}</span>
<span class="p">)</span>
<span class="nb">target_compile_options</span><span class="p">(</span><span class="s">cust_op_proto</span><span class="w"> </span><span class="s">PRIVATE</span><span class="w"> </span><span class="s">-fvisibility=hidden</span><span class="p">)</span>

<span class="c"># 4. 编译Tiling库</span>
<span class="nb">file</span><span class="p">(</span><span class="s">GLOB</span><span class="w"> </span><span class="s">fallback_src</span><span class="w"> </span><span class="o">\${</span><span class="nv">ASCEND_AUTOGEN_PATH</span><span class="o">}</span><span class="s">/fallback_*.cpp</span><span class="p">)</span>
<span class="nb">set_source_files_properties</span><span class="p">(</span><span class="o">\${</span><span class="nv">fallback_src</span><span class="o">}</span><span class="w"> </span><span class="s">PROPERTIES</span><span class="w"> </span><span class="s">GENERATED</span><span class="w"> </span><span class="s">TRUE</span><span class="p">)</span>
<span class="nb">npu_op_library</span><span class="p">(</span><span class="s">cust_optiling</span><span class="w"> </span><span class="s">TILING</span>
<span class="w">    </span><span class="o">\${</span><span class="nv">ops_srcs</span><span class="o">}</span>
<span class="w">    </span><span class="o">\${</span><span class="nv">fallback_src</span><span class="o">}</span>
<span class="p">)</span>
<span class="nb">target_compile_options</span><span class="p">(</span><span class="s">cust_optiling</span><span class="w"> </span><span class="s">PRIVATE</span><span class="w"> </span><span class="s">-fvisibility=hidden</span><span class="p">)</span>

<span class="c"># 5. 添加Host侧库到package</span>
<span class="nb">npu_op_package_add</span><span class="p">(</span><span class="o">\${</span><span class="nv">package_name</span><span class="o">}</span>
<span class="w">    </span><span class="s">LIBRARY</span>
<span class="w">        </span><span class="s">cust_optiling</span>
<span class="w">        </span><span class="s">cust_opapi</span>
<span class="w">        </span><span class="s">cust_op_proto</span>
<span class="p">)</span>
</code></pre></div><p><strong>3. 核函数（Kernel）侧CMakeLists.txt</strong></p><p><code>op_kernel/</code>下的CMakeLists.txt配置核函数（Kernel）编译选项、指定源码，并编译核函数（Kernel）库：</p><ol><li><p>使用<strong>npu_op_kernel_options</strong>添加<a href="#%E8%87%AA%E5%AE%9A%E4%B9%89%E7%BC%96%E8%AF%91%E9%80%89%E9%A1%B9%E8%BF%9B%E9%98%B6">算子编译选项</a>。</p></li><li><p>使用<strong>npu_op_kernel_sources</strong>指定算子特定目录与编译源文件。</p><ul><li>若算子的源码文件没有平铺在<code>SRC_BASE</code>目录（通过<code>npu_op_kernel_library</code>设置）下，可以通过<code>KERNEL_DIR</code>指定特定目录。</li><li>若算子的核函数（Kernel）实现cpp文件需要自定义命名，需同时指定<code>OP_TYPE</code>（算子类型）和<code>KERNEL_FILE</code>（核函数（Kernel）实现cpp文件名），以配置两者之间的对应关系。不配置时，核函数（Kernel）实现cpp文件名和OpType之间需满足<a href="../appendix/naming_conversion_table.html">转换规则</a>。</li></ul></li><li><p>使用<strong>npu_op_kernel_library</strong>编译核函数（Kernel）库。</p></li><li><p>使用<strong>npu_op_package_add</strong>添加上述核函数（Kernel）侧库到对应package中。</p></li></ol><div class="code-block"><div class="code-header"><span class="lang-label">CMake</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c"># 1. 设置核函数（Kernel）编译选项</span>
<span class="nb">npu_op_kernel_options</span><span class="p">(</span><span class="s">ascendc_kernels</span><span class="w"> </span><span class="s">ALL</span><span class="w"> </span><span class="s">OPTIONS</span><span class="w"> </span><span class="s">--save-temp-files</span><span class="w"> </span><span class="s">-g</span><span class="p">)</span>

<span class="c"># 2. 指定核函数（Kernel）源码</span>
<span class="nb">npu_op_kernel_sources</span><span class="p">(</span><span class="s">ascendc_kernels</span>
<span class="w">    </span><span class="s">OP_TYPE</span><span class="w"> </span><span class="s">AddCustom</span><span class="w">                              </span><span class="c">#算子类型</span>
<span class="w">    </span><span class="s">COMPUTE_UNIT</span><span class="w"> </span><span class="s">ascendxxxyy</span><span class="w">                       </span><span class="c"># AI处理器型号</span>
<span class="w">    </span><span class="s">KERNEL_FILE</span><span class="w"> </span><span class="s">add_custom.cpp</span><span class="w">                     </span><span class="c"># kernel实现文件名</span>
<span class="p">)</span>
<span class="err">或者</span>
<span class="nb">npu_op_kernel_sources</span><span class="p">(</span><span class="s">ascendc_kernels</span>
<span class="w">    </span><span class="s">OP_TYPE</span><span class="w"> </span><span class="s">AddCustom</span><span class="w">                              </span><span class="c">#算子类型</span>
<span class="w">    </span><span class="s">SOC_SERIES</span><span class="w"> </span><span class="s">Ascendxxx</span><span class="w">                           </span><span class="c"># AI处理器型号</span>
<span class="w">    </span><span class="s">KERNEL_FILE</span><span class="w"> </span><span class="s">add_custom.cpp</span><span class="w">                     </span><span class="c"># kernel实现文件名</span>
<span class="p">)</span>

<span class="c"># 3. 编译核函数（Kernel）库</span>
<span class="nb">npu_op_kernel_library</span><span class="p">(</span><span class="s">ascendc_kernels</span>
<span class="w">    </span><span class="s">SRC_BASE</span><span class="w"> </span><span class="o">\${</span><span class="nv">CMAKE_SOURCE_DIR</span><span class="o">}</span><span class="s">/op_kernel/</span><span class="w">        </span><span class="c"># 核函数（Kernel）源码根目录</span>
<span class="w">    </span><span class="s">TILING_LIBRARY</span><span class="w"> </span><span class="s">cust_optiling</span><span class="w">                   </span><span class="c">#依赖的Tiling库</span>
<span class="p">)</span>

<span class="c"># 4. 添加核函数（Kernel）库到package</span>
<span class="nb">npu_op_package_add</span><span class="p">(</span><span class="o">\${</span><span class="nv">package_name</span><span class="o">}</span>
<span class="w">    </span><span class="s">LIBRARY</span><span class="w"> </span><span class="s">ascendc_kernels</span>
<span class="p">)</span>
</code></pre></div><p>示例中核函数（Kernel）实现文件名为<code>add_custom.cpp</code>，所以在<code>npu_op_kernel_sources</code>中同时指定了<code>OP_TYPE</code>和<code>KERNEL_FILE</code>。如果想按目录扫描核函数（Kernel）源码，可改用<code>KERNEL_DIR ./</code>，此时<code>KERNEL_DIR</code>相对于后续<code>npu_op_kernel_library</code>中的<code>SRC_BASE</code>。</p><h3 id="按算子划分的目录结构">按算子划分的目录结构<a class="header-anchor" href="#按算子划分的目录结构">​</a></h3><p>工程包含多个算子且各算子独立性较高时，按算子划分更方便维护——每个算子的Host、核函数（Kernel）、Tiling文件放在同一目录，新增算子只需添加一个独立子目录。</p><p>下面示例在顶层CMakeLists.txt中集中列出各算子的Host源文件，并通过<code>npu_op_kernel_sources</code>声明各算子的核函数（Kernel）源码信息，最终仍由<code>npu_op_code_gen</code>、<code>npu_op_library</code>、<code>npu_op_kernel_library</code>和<code>npu_op_package_add</code>完成代码生成、编译和打包。</p><p><strong>1. 目录结构</strong></p><p>以AddCustom、AddCustom2、AddCustom3三个算子为例：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>add_custom/
├── add_custom.cpp           # Host侧原型定义、Shape推导、Tiling实现
├── add_custom_kernel.cpp    # 核函数（Kernel）实现
└── add_custom_tiling.h      # Tiling数据结构定义
add_custom2/
├── add_custom2.cpp
├── add_custom2_kernel.cpp
└── add_custom2_tiling.h
add_custom3/
├── add_custom3.cpp
├── add_custom3_kernel.cpp
└── add_custom3_tiling.h
</code></pre></div><p><strong>2. 顶层CMakeLists.txt</strong></p><p>顶层CMakeLists.txt设置编译环境、定义package形态，声明各算子的Host/核函数（Kernel）文件，并完成Host侧库、核函数（Kernel）侧库和算子包打包。</p><div class="code-block"><div class="code-header"><span class="lang-label">CMake</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="nb">cmake_minimum_required</span><span class="p">(</span><span class="s">VERSION</span><span class="w"> </span><span class="s">3.19.0</span><span class="p">)</span>
<span class="nb">project</span><span class="p">(</span><span class="s">opp</span><span class="p">)</span>

<span class="c"># 查找CANN提供的ASC CMake modules。ASCEND_CANN_PACKAGE_PATH通常在CMakePresets.json中配置。</span>
<span class="nb">find_package</span><span class="p">(</span><span class="s">ASC</span><span class="w"> </span><span class="s">REQUIRED</span><span class="w"> </span><span class="s">HINTS</span><span class="w"> </span><span class="o">\${</span><span class="nv">ASCEND_CANN_PACKAGE_PATH</span><span class="o">}</span><span class="s">/compiler/tikcpp/ascendc_kernel_cmake</span><span class="p">)</span>

<span class="c"># vendor_name在CMakePresets.json中配置，用作算子包的厂商标识。npu_op_package定义一个算子包目标</span>
<span class="nb">set</span><span class="p">(</span><span class="s">package_name</span><span class="w"> </span><span class="o">\${</span><span class="nv">vendor_name</span><span class="o">}</span><span class="p">)</span>
<span class="nb">npu_op_package</span><span class="p">(</span><span class="o">\${</span><span class="nv">package_name</span><span class="o">}</span>
<span class="w">    </span><span class="s">TYPE</span><span class="w"> </span><span class="s">RUN</span>
<span class="w">    </span><span class="s">CONFIG</span>
<span class="w">        </span><span class="s">INSTALL_PATH</span><span class="w"> </span><span class="o">\${</span><span class="nv">CMAKE_BINARY_DIR</span><span class="o">}</span><span class="s">/</span>
<span class="p">)</span>

<span class="c"># 1. 声明所有算子的Host源文件。</span>
<span class="nb">set</span><span class="p">(</span><span class="s">ops_srcs</span>
<span class="w">    </span><span class="o">\${</span><span class="nv">CMAKE_CURRENT_SOURCE_DIR</span><span class="o">}</span><span class="s">/add_custom/add_custom.cpp</span>
<span class="w">    </span><span class="o">\${</span><span class="nv">CMAKE_CURRENT_SOURCE_DIR</span><span class="o">}</span><span class="s">/add_custom2/add_custom2.cpp</span>
<span class="w">    </span><span class="o">\${</span><span class="nv">CMAKE_CURRENT_SOURCE_DIR</span><span class="o">}</span><span class="s">/add_custom3/add_custom3.cpp</span>
<span class="p">)</span>

<span class="c"># 2. 统一生成aclnn调用代码和原型定义代码。</span>
<span class="c"># npu_op_code_gen必须先于npu_op_kernel_sources调用，</span>
<span class="c"># 因为npu_op_kernel_sources依赖这里设置的自动生成文件路径。</span>
<span class="nb">npu_op_code_gen</span><span class="p">(</span>
<span class="w">    </span><span class="s">SRC</span><span class="w"> </span><span class="o">\${</span><span class="nv">ops_srcs</span><span class="o">}</span>
<span class="w">    </span><span class="s">PACKAGE</span><span class="w"> </span><span class="o">\${</span><span class="nv">package_name</span><span class="o">}</span>
<span class="w">    </span><span class="s">OUT_DIR</span><span class="w"> </span><span class="o">\${</span><span class="nv">ASCEND_AUTOGEN_PATH</span><span class="o">}</span>
<span class="p">)</span>

<span class="c"># 3. 编译aclnn单算子调用库。</span>
<span class="c"># npu_op_code_gen执行后，ASCEND_AUTOGEN_PATH下会生成aclnn_*.cpp/aclnn_*.h。</span>
<span class="nb">file</span><span class="p">(</span><span class="s">GLOB</span><span class="w"> </span><span class="s">autogen_aclnn_src</span><span class="w"> </span><span class="o">\${</span><span class="nv">ASCEND_AUTOGEN_PATH</span><span class="o">}</span><span class="s">/aclnn_*.cpp</span><span class="p">)</span>
<span class="nb">set_source_files_properties</span><span class="p">(</span><span class="o">\${</span><span class="nv">autogen_aclnn_src</span><span class="o">}</span><span class="w"> </span><span class="s">PROPERTIES</span><span class="w"> </span><span class="s">GENERATED</span><span class="w"> </span><span class="s">TRUE</span><span class="p">)</span>
<span class="nb">npu_op_library</span><span class="p">(</span><span class="s">cust_opapi</span><span class="w"> </span><span class="s">ACLNN</span>
<span class="w">    </span><span class="o">\${</span><span class="nv">autogen_aclnn_src</span><span class="o">}</span>
<span class="p">)</span>
<span class="nb">target_compile_options</span><span class="p">(</span><span class="s">cust_opapi</span><span class="w"> </span><span class="s">PRIVATE</span><span class="w"> </span><span class="s">-fvisibility=hidden</span><span class="p">)</span>

<span class="c"># 4. 编译算子原型库（用于入图）。</span>
<span class="c"># 原型库同时依赖各算子的Host源文件和自动生成的op_proto代码。</span>
<span class="nb">file</span><span class="p">(</span><span class="s">GLOB</span><span class="w"> </span><span class="s">group_proto_src</span><span class="w"> </span><span class="o">\${</span><span class="nv">ASCEND_AUTOGEN_PATH</span><span class="o">}</span><span class="s">/group_op_proto/*.cc</span><span class="p">)</span>
<span class="nb">file</span><span class="p">(</span><span class="s">GLOB</span><span class="w"> </span><span class="s">proto_src</span><span class="w"> </span><span class="o">\${</span><span class="nv">ASCEND_AUTOGEN_PATH</span><span class="o">}</span><span class="s">/op_proto.cc</span><span class="p">)</span>
<span class="nb">set_source_files_properties</span><span class="p">(</span><span class="o">\${</span><span class="nv">group_proto_src</span><span class="o">}</span><span class="w"> </span><span class="s">PROPERTIES</span><span class="w"> </span><span class="s">GENERATED</span><span class="w"> </span><span class="s">TRUE</span><span class="p">)</span>
<span class="nb">set_source_files_properties</span><span class="p">(</span><span class="o">\${</span><span class="nv">proto_src</span><span class="o">}</span><span class="w"> </span><span class="s">PROPERTIES</span><span class="w"> </span><span class="s">GENERATED</span><span class="w"> </span><span class="s">TRUE</span><span class="p">)</span>
<span class="nb">npu_op_library</span><span class="p">(</span><span class="s">cust_op_proto</span><span class="w"> </span><span class="s">GRAPH</span>
<span class="w">    </span><span class="o">\${</span><span class="nv">ops_srcs</span><span class="o">}</span>
<span class="w">    </span><span class="o">\${</span><span class="nv">group_proto_src</span><span class="o">}</span>
<span class="w">    </span><span class="o">\${</span><span class="nv">proto_src</span><span class="o">}</span>
<span class="p">)</span>
<span class="nb">target_compile_options</span><span class="p">(</span><span class="s">cust_op_proto</span><span class="w"> </span><span class="s">PRIVATE</span><span class="w"> </span><span class="s">-fvisibility=hidden</span><span class="p">)</span>

<span class="c"># 5. 编译Tiling库。</span>
<span class="c"># Tiling实现位于各算子的Host源文件中；fallback_*.cpp为npu_op_code_gen生成的辅助代码。</span>
<span class="nb">file</span><span class="p">(</span><span class="s">GLOB</span><span class="w"> </span><span class="s">fallback_src</span><span class="w"> </span><span class="o">\${</span><span class="nv">ASCEND_AUTOGEN_PATH</span><span class="o">}</span><span class="s">/fallback_*.cpp</span><span class="p">)</span>
<span class="nb">set_source_files_properties</span><span class="p">(</span><span class="o">\${</span><span class="nv">fallback_src</span><span class="o">}</span><span class="w"> </span><span class="s">PROPERTIES</span><span class="w"> </span><span class="s">GENERATED</span><span class="w"> </span><span class="s">TRUE</span><span class="p">)</span>
<span class="nb">npu_op_library</span><span class="p">(</span><span class="s">cust_optiling</span><span class="w"> </span><span class="s">TILING</span>
<span class="w">    </span><span class="o">\${</span><span class="nv">ops_srcs</span><span class="o">}</span>
<span class="w">    </span><span class="o">\${</span><span class="nv">fallback_src</span><span class="o">}</span>
<span class="p">)</span>
<span class="nb">target_compile_options</span><span class="p">(</span><span class="s">cust_optiling</span><span class="w"> </span><span class="s">PRIVATE</span><span class="w"> </span><span class="s">-fvisibility=hidden</span><span class="p">)</span>

<span class="c"># 6. 声明各算子的核函数（Kernel）源码信息。</span>
<span class="c"># KERNEL_DIR相对于下面npu_op_kernel_library的SRC_BASE。</span>
<span class="nb">npu_op_kernel_sources</span><span class="p">(</span><span class="s">ascendc_kernels</span>
<span class="w">    </span><span class="s">OP_TYPE</span><span class="w"> </span><span class="s">AddCustom</span>
<span class="w">    </span><span class="s">KERNEL_DIR</span><span class="w"> </span><span class="s">add_custom</span>
<span class="w">    </span><span class="s">KERNEL_FILE</span><span class="w"> </span><span class="s">add_custom_kernel.cpp</span>
<span class="p">)</span>
<span class="nb">npu_op_kernel_sources</span><span class="p">(</span><span class="s">ascendc_kernels</span>
<span class="w">    </span><span class="s">OP_TYPE</span><span class="w"> </span><span class="s">AddCustom2</span>
<span class="w">    </span><span class="s">KERNEL_DIR</span><span class="w"> </span><span class="s">add_custom2</span>
<span class="w">    </span><span class="s">KERNEL_FILE</span><span class="w"> </span><span class="s">add_custom2_kernel.cpp</span>
<span class="p">)</span>
<span class="nb">npu_op_kernel_sources</span><span class="p">(</span><span class="s">ascendc_kernels</span>
<span class="w">    </span><span class="s">OP_TYPE</span><span class="w"> </span><span class="s">AddCustom3</span>
<span class="w">    </span><span class="s">KERNEL_DIR</span><span class="w"> </span><span class="s">add_custom3</span>
<span class="w">    </span><span class="s">KERNEL_FILE</span><span class="w"> </span><span class="s">add_custom3_kernel.cpp</span>
<span class="p">)</span>

<span class="c"># 7. 编译核函数（Kernel）库。</span>
<span class="c"># SRC_BASE是所有算子目录共同的源码根目录；TILING_LIBRARY指向上面编译出的Tiling库。</span>
<span class="nb">npu_op_kernel_library</span><span class="p">(</span><span class="s">ascendc_kernels</span>
<span class="w">    </span><span class="s">SRC_BASE</span><span class="w"> </span><span class="o">\${</span><span class="nv">CMAKE_CURRENT_SOURCE_DIR</span><span class="o">}</span><span class="s">/</span>
<span class="w">    </span><span class="s">TILING_LIBRARY</span><span class="w"> </span><span class="s">cust_optiling</span>
<span class="p">)</span>

<span class="c"># 8. 将Host侧库和核函数（Kernel）库加入算子包，最终生成run包。</span>
<span class="nb">npu_op_package_add</span><span class="p">(</span><span class="o">\${</span><span class="nv">package_name</span><span class="o">}</span>
<span class="w">    </span><span class="s">LIBRARY</span>
<span class="w">        </span><span class="s">cust_optiling</span>
<span class="w">        </span><span class="s">cust_opapi</span>
<span class="w">        </span><span class="s">cust_op_proto</span>
<span class="w">        </span><span class="s">ascendc_kernels</span>
<span class="p">)</span>
</code></pre></div><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><ul><li>示例在顶层集中列出各算子的Host源文件和核函数（Kernel）源码信息，是为了展示<code>npu_op_*</code>接口的调用关系；如果工程有自己的目录封装，只要最终传给<code>npu_op_code_gen</code>的Host源文件、传给<code>npu_op_kernel_sources</code>的<code>OP_TYPE</code>/<code>KERNEL_DIR</code>/<code>KERNEL_FILE</code>，以及传给<code>npu_op_kernel_library</code>的<code>SRC_BASE</code>匹配即可。</li><li><code>npu_op_kernel_sources</code>依赖<code>npu_op_code_gen</code>设置的自动生成文件路径，因此需要在<code>npu_op_code_gen</code>之后调用。</li><li><code>OP_TYPE</code>需要与算子原型注册中的OpType一致；当核函数（Kernel）文件名不是OpType默认转换后的文件名时，需要显式指定<code>KERNEL_FILE</code>。</li><li>新增算子时，只需要新增算子子目录，在<code>ops_srcs</code>中追加Host源文件，并新增一组<code>npu_op_kernel_sources</code>配置。</li></ul></div><p><strong>与&quot;按Host/核函数（Kernel）划分&quot;的关键差异</strong>：</p><ul><li>Host侧源文件按算子目录列出，顶层统一调用<code>npu_op_code_gen</code>。</li><li>核函数（Kernel）源码信息按算子目录声明，顶层在<code>npu_op_code_gen</code>后统一调用<code>npu_op_kernel_sources</code>。</li><li><code>SRC_BASE</code>指向所有算子目录共同的源码根目录，<code>KERNEL_DIR</code>指向具体算子子目录。</li><li>各算子的Host、核函数（Kernel）、Tiling文件集中在同一目录下。</li></ul><blockquote><p>详细cmake函数参数请参考<a href="../appendix/cmake_function_reference.html">cmake函数参考</a>。</p></blockquote><p>完成编译组织之后，可按照<a href="#%E5%9F%BA%E6%9C%AC%E6%B5%81%E7%A8%8B">基本流程</a>的三个步骤完成算子编译与部署。</p><p><a id="自定义编译选项"></a></p><h2 id="自定义编译选项（进阶）">自定义编译选项（进阶）<a id="custom-compile-options"></a><a class="header-anchor" href="#自定义编译选项（进阶）">​</a></h2><p>在CMakeLists.txt中，用<code>npu_op_kernel_options</code>为核函数（Kernel）侧代码添加编译选项：</p><div class="code-block"><div class="code-header"><span class="lang-label">CMake</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="nb">npu_op_kernel_options</span><span class="p">(</span><span class="s">&lt;target_name&gt;</span><span class="w"> </span><span class="s">&lt;op_type&gt;</span><span class="w"> </span><span class="s">[COMPUTE_UNIT</span><span class="w"> </span><span class="s">&lt;soc_version&gt;...</span><span class="w"> </span><span class="s">|</span><span class="w"> </span><span class="s">SOC_SERIES</span><span class="w"> </span><span class="s">&lt;series&gt;...]</span><span class="w"> </span><span class="s">OPTIONS</span><span class="w"> </span><span class="s">...</span><span class="p">)</span>
</code></pre></div><p><strong>表4</strong> 参数说明。</p><table><thead><tr><th>参数名称</th><th>可选/必选</th><th>参数描述</th></tr></thead><tbody><tr><td>target_name</td><td>必选</td><td>核函数（Kernel）库的目标名称（如<code>ascendc_kernels</code>）。</td></tr><tr><td>op_type</td><td>必选</td><td>算子类型。如需对所有算子生效，配置为<code>ALL</code>。</td></tr><tr><td>COMPUTE_UNIT</td><td>可选</td><td>AI处理器型号，不配置时对所有型号生效。与<code>SOC_SERIES</code>不能同时使用。</td></tr><tr><td>SOC_SERIES</td><td>可选</td><td>AI处理器系列，输入不区分大小写。与<code>COMPUTE_UNIT</code>不能同时使用。</td></tr><tr><td>OPTIONS</td><td>必选</td><td>自定义编译选项，多个选项用空格间隔。支持<code>--save-temp-files</code>、<code>-g</code>、<code>-DASCENDC_DEBUG</code>等。</td></tr></tbody></table><p><strong>常见示例</strong>：</p><div class="code-block"><div class="code-header"><span class="lang-label">CMake</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c"># 为所有算子保留核函数（Kernel）编译中间产物</span>
<span class="nb">npu_op_kernel_options</span><span class="p">(</span><span class="s">ascendc_kernels</span><span class="w"> </span><span class="s">ALL</span><span class="w"> </span><span class="s">OPTIONS</span><span class="w"> </span><span class="s">--save-temp-files</span><span class="p">)</span>

<span class="c"># 为特定算子在特定型号上开启AscendC调试宏</span>
<span class="nb">npu_op_kernel_options</span><span class="p">(</span><span class="s">ascendc_kernels</span><span class="w"> </span><span class="s">AddCustom</span><span class="w"> </span><span class="s">COMPUTE_UNIT</span><span class="w"> </span><span class="s">ascendxxxyy</span><span class="w"> </span><span class="s">OPTIONS</span><span class="w"> </span><span class="s">-DASCENDC_DEBUG</span><span class="p">)</span>

<span class="c"># 使用SOC_SERIES按系列配置，多个值用空格分隔</span>
<span class="nb">npu_op_kernel_options</span><span class="p">(</span><span class="s">ascendc_kernels</span><span class="w"> </span><span class="s">AddCustom</span><span class="w"> </span><span class="s">SOC_SERIES</span><span class="w"> </span><span class="s">Ascendxxx</span><span class="w"> </span><span class="s">OPTIONS</span><span class="w"> </span><span class="s">-DASCENDC_DEBUG</span><span class="p">)</span>
</code></pre></div><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><ul><li>编译选项是基于“算子类型+AI处理器型号系列”进行配置的，也就是说不同的“算子类型+AI处理器型号系列”可以配置不同的编译选项。</li><li>对相同算子类型+AI处理器型号系列，做多次编译选项配置，以后配置的为准。</li><li>对ALL生效的编译选项和对单一算子生效的编译选项如果没有冲突，同时生效，如果有冲突，以单一算子的编译选项为准。</li></ul></div><p>Ascend C框架提供的编译选项介绍如下：</p><ul><li><p><code>--tiling_key</code>，设置该选项后，只编译指定的<a href="../design_and_implementation/multi_branch_strategy.html#compile-selected-tiling-keys">TilingKey</a>相关的核函数（Kernel）代码，用于加速编译过程。若不指定TilingKey编译，则默认编译所有的TilingKey。配置多个TilingKey时，TilingKey之间不能有空格。示例如下，其中1、2为TilingKey取值。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>--tiling_key=1,2
</code></pre></div></li><li><p>编译宏开关请参考<a href="../../../compilation_and_execution/operator_compilation/ai_core_operator_compilation.html">内置编译宏开关</a>。</p></li><li><p><code>--op_relocatable_kernel_binary</code>，设置该选项为true时，会额外编译一份可被重新链接的二进制文件；不配置或设置为false时该选项均不生效。该选项用于自定义Tiling下沉算子开启SuperKernel的场景，配置该选项所生成的二进制文件，可以使算子在SuperKernel编译时直接复用二进制文件，降低编译耗时。</p></li><li><p><code>--kernel-template-input</code>，编译指定的模板参数组合相关的核函数（Kernel）代码，用于加速编译过程。更多信息参考<a href="./compilation_acceleration.html#%E9%80%89%E6%8B%A9%E6%80%A7%E7%BC%96%E8%AF%91">编译加速 — 选择性编译</a>。</p></li><li><p><code>-DFORCE_TILING_CONST_PROPAGATION</code>，该选项用于静态shape场景Tiling数据的常量化优化。对于复杂算子，该编译选项可以提升算子静态shape执行性能。该编译选项仅支持自定义算子工程，且仅在算子使用<code>BEGIN_TILING_DATA_DEF</code>注册Tiling结构体的情形下生效，对于算子使用标准C++语法定义Tiling结构体的情形下不生效。使用示例如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>-DFORCE_TILING_CONST_PROPAGATION
</code></pre></div><p>该编译选项的原理是，在算子使用<code>BEGIN_TILING_DATA_DEF</code>注册Tiling结构体的场景下，自定义算子工程在定义该Tiling结构体时，会将其成员变量都定义为static constexpr类型常量，即将Tiling结构体变为静态常量类。由于在前端标记了常量，编译器会根据Tiling数据进行更彻底的常量折叠和优化。</p><p>该选项对算子写法有约束，以下情形不支持该选项：</p><ol><li><p>算子代码中不允许有用Tiling结构体定义非const对象，也不允许对Tiling对象的成员进行赋值操作。否则会有编译错误。原因是静态常量无法被重新赋值。</p></li><li><p>算子代码中不允许有<code>reinterpret_cast&lt;OtherType*&gt;(tiling_data)</code>的行为，否则会得到非预期的结果。这是因为Tiling结构体所有成员都是常量，该类型的对象没有实体，size恒为1字节，对<code>tiling_data</code>的<code>reinterpret_cast</code>会产生未定义的行为。</p></li></ol><p>对于算子使用标准C++语法定义Tiling结构体的情形下不生效的原因是，算子定义Tiling结构体为static constexpr时，无法获得Tiling数据，无法给Tiling结构体成员在定义时初始化。</p></li><li><p>--save-temp-files，该选项用于保留核函数（Kernel）侧编译过程中生成的临时文件。在编译过程中会根据芯片类型、输入输出的dtype/format等因素排列组合触发不同的<code>kernel.o</code>编译，开启该选项，可查看每个<code>kernel.o</code>的编译过程，用于辅助定位问题。</p><p>添加该编译选项并执行工程编译，可在<code>build/op_kernel/&lt;OpType&gt;_&lt;soc&gt;/kernel_*/kernel_meta_*/kernel_meta</code>目录查看实际参与编译的核函数（Kernel）源码、编译命令等中间文件，其中<code>&lt;OpType&gt;</code>表示算子类型，<code>&lt;soc&gt;</code>表示编译目标芯片类型。</p></li></ul><h2 id="相关文档">相关文档<a class="header-anchor" href="#相关文档">​</a></h2><ul><li><a href="../invocation/single_operator_api_call.html">单算子API调用</a> — 调用编译部署后的算子。</li><li><a href="./multi_operator_package.html">多算子包组织</a> — 是否需要算子拆包建议。</li><li><a href="./dynamic_static_lib_compilation.html">算子动态库和静态库编译</a> — 动态库/静态库编译方式。</li><li><a href="./compilation_debug.html">编译过程调试</a> — 查看实际编译命令、保留中间产物和常见错误诊断。</li><li><a href="./compilation_acceleration.html">编译加速</a> — 构建加速策略（选择性编译、缓存、增量编译等）。</li><li><a href="./simplified_key_json_configuration.html">simplified key二进制配置JSON</a> — 按自定义simplified key编译多份binary的配置方法。</li><li><a href="./cross_compilation.html">交叉编译</a> — 跨平台架构编译。</li></ul></article></div>`,1)])])}const g=a(e,[["render",o]]);export{v as __pageData,g as default};
